import{j as i,w as d,t,J as a,bC as n,I as s,H as r,aT as o,aG as l}from"./index-C9ruY_Ly.js";const c={},h={class:"lesson-page"},b={class:"shell"},f=r('<header data-v-f94b7740><p class="eyebrow" data-v-f94b7740>ADOBE INDESIGN · MINI TUTORIAL</p><h1 data-v-f94b7740>Textrahmen automatisch an Text anpassen</h1><p class="goal" data-v-f94b7740>Dein Textrahmen wächst mit, wenn du den Inhalt oder die Schriftgestaltung veränderst.</p></header><section aria-labelledby="terms-title" data-v-f94b7740><h2 id="terms-title" data-v-f94b7740>Einfach erklärt</h2><dl data-v-f94b7740><div data-v-f94b7740><dt data-v-f94b7740>Automatische Größenänderung</dt><dd data-v-f94b7740>InDesign passt die Größe des Textrahmens an seinen Inhalt an. Du legst fest, welche Dimensionen sich ändern dürfen.</dd></div><div data-v-f94b7740><dt data-v-f94b7740>Bezugspunkt</dt><dd data-v-f94b7740>Dieser Punkt bleibt an seiner Position, wenn der Rahmen wächst oder schrumpft.</dd></div></dl></section><section class="practice" aria-labelledby="practice-title" data-v-f94b7740><h2 id="practice-title" data-v-f94b7740>So gehst du vor</h2><ol data-v-f94b7740><li data-v-f94b7740>Wähle deinen <strong data-v-f94b7740>Textrahmen</strong> aus.</li><li data-v-f94b7740>Gehe zu <strong data-v-f94b7740>Objekt → Textrahmenoptionen (⌘ + B)</strong>.</li><li data-v-f94b7740>Wechsle zum Reiter <strong data-v-f94b7740>Automatisch Größe ändern</strong>.</li><li data-v-f94b7740>Wähle bei <strong data-v-f94b7740>„Automatische Größenänderung“</strong> die Option <strong data-v-f94b7740>Nur Höhe</strong>.</li><li data-v-f94b7740>Wähle als Bezugspunkt <strong data-v-f94b7740>oben mittig</strong>, damit der Textrahmen nach unten wächst. Bestätige mit <strong data-v-f94b7740>OK</strong>.</li></ol><p data-v-f94b7740>Jetzt passt sich die Höhe des Textrahmens automatisch an den Inhalt an – auch wenn du Schriftgröße oder Zeilenabstand veränderst.</p></section><section class="practice" aria-labelledby="tip-title" data-v-f94b7740><h2 id="tip-title" data-v-f94b7740>Praktischer Tipp</h2><p data-v-f94b7740>Mit einem <strong data-v-f94b7740>Doppelklick auf einen Anfasser</strong> des Textrahmens kannst du den Rahmen auch einmalig an den Text anpassen.</p><p data-v-f94b7740>Ein Anfasser ist eines der <strong data-v-f94b7740>acht kleinen Quadrate am Rand des ausgewählten Rahmens</strong>.</p></section><section class="check" aria-labelledby="check-title" data-v-f94b7740><h2 id="check-title" data-v-f94b7740>Prüfe dein Ergebnis</h2><p data-v-f94b7740>Füge Text hinzu und verändere Schriftgröße oder Zeilenabstand. Wächst der Rahmen nach unten, während seine Breite und die obere Kante gleich bleiben?</p></section><section class="practice" aria-labelledby="example-title" data-v-f94b7740><h2 id="example-title" data-v-f94b7740>Beispieltext zum Ausprobieren</h2><p data-v-f94b7740>Dieser Text dient dazu, verschiedene Funktionen der Textgestaltung in Adobe InDesign auszuprobieren. Dabei können Schriftgröße, Zeilenabstand, Absatzabstände und die automatische Größenanpassung von Textrahmen getestet werden.</p></section>',6),u={class:"pager","aria-label":"Tutorialnavigation"};function v(p,g){const e=o("RouterLink");return l(),d("main",h,[t("div",b,[a(e,{to:"/medientechnik/adobe-indesign/mini-tutorials",class:"back"},{default:n(()=>[s("← Mini Tutorials")]),_:1}),f,t("nav",u,[a(e,{to:"/medientechnik/adobe-indesign/mini-tutorials"},{default:n(()=>[s("← Zur Übersicht")]),_:1})])])])}const x=i(c,[["render",v],["__scopeId","data-v-f94b7740"]]);export{x as default};
